  const state = { lastLat: null, lastLng: null, lastCountry: null };
  let btnRef = null;

  // ---------- GeoGuessr Event Framework から正解地点を取得 ----------
  function onRoundEnd(event) {
    try {
      const detail = event.detail;
      if (detail && Array.isArray(detail.rounds) && detail.rounds.length > 0) {
        const last = detail.rounds[detail.rounds.length - 1];
        if (last && last.location && typeof last.location.lat === 'number' && typeof last.location.lng === 'number') {
          state.lastLat = last.location.lat;
          state.lastLng = last.location.lng;
          LOG('正解座標を取得:', state.lastLat, state.lastLng);
          state.lastCountry = resolveCountry(state.lastLat, state.lastLng);
          showButtonWithCountry(state.lastCountry);
          return;
        }
      }
    } catch (e) {
      LOG('round_end の処理でエラー:', e);
    }
  }

  function onRoundStart() {
    state.lastLat = null;
    state.lastLng = null;
    state.lastCountry = null;
    hideButton();
  }

  function waitForFrameworkAndSubscribe(retriesLeft) {
    const GEF = pageWindow.GeoGuessrEventFramework;
    if (!GEF) {
      if (retriesLeft > 0) {
        setTimeout(() => waitForFrameworkAndSubscribe(retriesLeft - 1), 1000);
      } else {
        LOG('GeoGuessrEventFramework が見つかりませんでした。手入力のみ利用可能です。');
      }
      return;
    }
    const initResult = typeof GEF.init === 'function' ? GEF.init() : GEF;
    Promise.resolve(initResult).then((instance) => {
      const target = instance && instance.events ? instance.events : (GEF.events || GEF);
      if (!target || typeof target.addEventListener !== 'function') {
        LOG('イベント購読先が見つかりませんでした。');
        return;
      }
      target.addEventListener('round_start', onRoundStart);
      target.addEventListener('round_end', onRoundEnd);
      LOG('GeoGuessrEventFramework の購読を開始しました。');
    }).catch((e) => LOG('init() でエラー:', e));
  }

  waitForFrameworkAndSubscribe(15);

